  1→using System.Security.Claims;
  2→using Microsoft.AspNetCore.Authorization;
  3→using Microsoft.AspNetCore.Mvc;
  4→using Microsoft.EntityFrameworkCore;
  5→using OmgtuPortal.Data;
  6→
  7→namespace OmgtuPortal.Controllers;
  8→
  9→[ApiController]
 10→[Route("api/control-work")]
 11→[Authorize(Roles = "teacher,admin")]
 12→public class ControlWorkController(AppDbContext db, AppSettings settings) : ControllerBase
 13→{
 14→    /// <summary>
 15→    /// Загрузка контрольной работы. Файл сохраняется на диск, метаданные — в БД.
 16→    /// </summary>
 17→    [HttpPost("upload")]
 18→    [RequestSizeLimit(50 * 1024 * 1024)]
 19→    public async Task<IActionResult> Upload(
 20→        [FromForm] string subjectId,
 21→        [FromForm] string groupId,
 22→        IFormFile file)
 23→    {
 24→        if (file.Length == 0)
 25→            return BadRequest(new { Error = "Файл пустой" });
 26→
 27→        var maxBytes = settings.MaxFileSizeMb * 1024 * 1024;
 28→        if (file.Length > maxBytes)
 29→            return BadRequest(new { Error = $"Файл превышает {settings.MaxFileSizeMb} МБ" });
 30→
 31→        var uploadsDir = Path.Combine(Directory.GetCurrentDirectory(), settings.UploadsPath);
 32→        Directory.CreateDirectory(uploadsDir);
 33→
 34→        var storedName = $"{Guid.NewGuid()}{Path.GetExtension(file.FileName)}";
 35→        var storedPath = Path.Combine(uploadsDir, storedName);
 36→
 37→        await using (var stream = new FileStream(storedPath, FileMode.Create))
 38→        {
 39→            await file.CopyToAsync(stream);
 40→        }
 41→
 42→        var userId = User.FindFirstValue(ClaimTypes.NameIdentifier)
 43→                     ?? User.FindFirstValue("sub")
 44→                     ?? "unknown";
 45→
 46→        var controlWork = new ControlWork
 47→        {
 48→            Id = Guid.NewGuid(),
 49→            SubjectId = subjectId,
 50→            GroupId = groupId,
 51→            FileName = file.FileName,
 52→            StoredPath = storedName,
 53→            ContentType = file.ContentType,
 54→            FileSize = file.Length,
 55→            UploadedBy = userId,
 56→            UploadedAt = DateTime.UtcNow,
 57→        };
 58→
 59→        db.ControlWorks.Add(controlWork);
 60→        await db.SaveChangesAsync();
 61→
 62→        return Created($"/api/control-work/{controlWork.Id}", new
 63→        {
 64→            controlWork.Id,
 65→            controlWork.SubjectId,
 66→            controlWork.GroupId,
 67→            controlWork.FileName,
 68→            controlWork.FileSize,
 69→            controlWork.UploadedAt,
 70→        });
 71→    }
 72→
 73→    /// <summary>
 74→    /// Список контрольных работ (опционально по группе).
 75→    /// </summary>
 76→    [HttpGet]
 77→    public async Task<IActionResult> GetAll([FromQuery] string? groupId)
 78→    {
 79→        var query = db.ControlWorks.AsQueryable();
 80→
 81→        if (!string.IsNullOrEmpty(groupId))
 82→            query = query.Where(c => c.GroupId == groupId);
 83→
 84→        var list = await query
 85→            .OrderByDescending(c => c.UploadedAt)
 86→            .Select(c => new
 87→            {
 88→                c.Id,
 89→                c.SubjectId,
 90→                c.GroupId,
 91→                c.FileName,
 92→                c.FileSize,
 93→                c.UploadedAt,
 94→            })
 95→            .ToListAsync();
 96→
 97→        return Ok(list);
 98→    }
 99→}
