 1→using Microsoft.AspNetCore.Authorization;
 2→using Microsoft.AspNetCore.Mvc;
 3→using Microsoft.EntityFrameworkCore;
 4→using OmgtuPortal.Data;
 5→using OmgtuPortal.University;
 6→
 7→namespace OmgtuPortal.Controllers;
 8→
 9→[ApiController]
10→[Route("api/contact-work")]
11→[Authorize(Roles = "student,admin")]
12→public class StudentFilesController(
13→    AppDbContext db,
14→    AppSettings settings,
15→    IUniversityClient universityClient) : ControllerBase
16→{
17→    /// <summary>
18→    /// Список файлов по группе и предмету. Студент может видеть только свою группу.
19→    /// </summary>
20→    [HttpGet("files")]
21→    public async Task<IActionResult> GetFiles([FromQuery] string groupId, [FromQuery] string subjectId)
22→    {
23→        var myGroupId = await GetMyGroupId();
24→        if (myGroupId is null)
25→            return NotFound(new { Error = "Группа студента не найдена" });
26→
27→        if (groupId != myGroupId)
28→            return Forbid();
29→
30→        var list = await db.ControlWorks
31→            .Where(c => c.GroupId == groupId && c.SubjectId == subjectId)
32→            .OrderByDescending(c => c.UploadedAt)
33→            .Select(c => new
34→            {
35→                c.Id,
36→                c.FileName,
37→                c.FileSize,
38→                c.ContentType,
39→                c.UploadedAt,
40→            })
41→            .ToListAsync();
42→
43→        return Ok(list);
44→    }
45→
46→    /// <summary>
47→    /// Скачивание файла по id. Доступен только файл, принадлежащий группе студента.
48→    /// </summary>
49→    [HttpGet("download/{fileId:guid}")]
50→    public async Task<IActionResult> Download(Guid fileId)
51→    {
52→        var myGroupId = await GetMyGroupId();
53→        if (myGroupId is null)
54→            return NotFound(new { Error = "Группа студента не найдена" });
55→
56→        var file = await db.ControlWorks.FirstOrDefaultAsync(c => c.Id == fileId);
57→        if (file is null)
58→            return NotFound(new { Error = "Файл не найден" });
59→
60→        if (file.GroupId != myGroupId)
61→            return Forbid();
62→
63→        var fullPath = Path.Combine(Directory.GetCurrentDirectory(), settings.UploadsPath, file.StoredPath);
64→        if (!System.IO.File.Exists(fullPath))
65→            return NotFound(new { Error = "Файл отсутствует на диске" });
66→
67→        var stream = new FileStream(fullPath, FileMode.Open, FileAccess.Read);
68→        return File(stream, file.ContentType, file.FileName);
69→    }
70→
71→    private async Task<string?> GetMyGroupId()
72→    {
73→        var sub = User.FindFirst("sub")?.Value;
74→        if (sub is null)
75→            return null;
76→
77→        return await universityClient.GetStudentGroupIdAsync(sub);
78→    }
79→}
