 1→namespace OmgtuPortal.University;
 2→
 3→public class LocalUniversityClient : IUniversityClient
 4→{
 5→    private static readonly IReadOnlyList<StudentGroup> Groups =
 6→    [
 7→        new("1", "ИВТ-111"),
 8→        new("2", "ИВТ-112"),
 9→        new("3", "ИВТ-211"),
10→        new("4", "ПМИ-101"),
11→        new("5", "ПМИ-201"),
12→        new("6", "ИСТ-101"),
13→        new("7", "ИСТ-201"),
14→        new("8", "МАТ-101"),
15→    ];
16→
17→    private static readonly Dictionary<string, string> SubToGroup = new()
18→    {
19→        ["dev-user-id"] = "1",
20→    };
21→
22→    public Task<IReadOnlyList<StudentGroup>> GetStudentGroupsAsync() =>
23→        Task.FromResult(Groups);
24→
