 1→using System.Net.Http.Json;
 2→
 3→namespace OmgtuPortal.University;
 4→
 5→public class HttpUniversityClient(HttpClient httpClient) : IUniversityClient
 6→{
 7→    public async Task<IReadOnlyList<StudentGroup>> GetStudentGroupsAsync()
 8→    {
 9→        var groups = await httpClient.GetFromJsonAsync<List<StudentGroup>>("groups");
10→        return groups ?? [];
11→    }
12→
13→    public async Task<string?> GetStudentGroupIdAsync(string sub)
14→    {
15→        var response = await httpClient.GetFromJsonAsync<GroupIdResponse>($"groups/{sub}");
16→        return response?.GroupId;
17→    }
18→
19→    private record GroupIdResponse(string? GroupId);
20→}
