  1→<script setup lang="ts">
  2→import { getUserRoles, logout } from '../auth'
  3→
  4→const roles = getUserRoles()
  5→
  6→interface NavItem {
  7→  label: string
  8→  to: string
  9→  roles?: string[]
 10→}
 11→
 12→const navItems: NavItem[] = [
 13→  { label: 'Главная', to: '/' },
 14→  { label: 'Преподаватель', to: '/teacher', roles: ['teacher', 'admin'] },
 15→]
 16→
 17→const visibleItems = navItems.filter((item) => {
 18→  if (!item.roles) return true
 19→  return item.roles.some((r) => roles.includes(r))
 20→})
 21→</script>
 22→
 23→<template>
 24→  <header class="app-header">
 25→    <nav class="nav-items">
 26→      <router-link
 27→        v-for="item in visibleItems"
 28→        :key="item.to"
 29→        :to="item.to"
 30→        class="nav-item"
 31→        exact-active-class="nav-item--active"
 32→      >
 33→        {{ item.label }}
 34→      </router-link>
 35→    </nav>
 36→    <button class="logout-btn" @click="logout()">Выход</button>
 37→  </header>
 38→</template>
 39→
 40→<style scoped>
 41→.app-header {
 42→  display: flex;
 43→  align-items: center;
 44→  justify-content: space-between;
 45→  padding: 0 1.5rem;
 46→  height: 3.5rem;
 47→  border-bottom: 1px solid var(--border);
 48→  background: var(--bg);
 49→  font-family: var(--sans);
 50→  position: sticky;
 51→  top: 0;
 52→  z-index: 100;
