 1→import Keycloak from 'keycloak-js'
 2→
 3→const ALL_ROLES = ['admin', 'user', 'student', 'teacher']
 4→
 5→let autoLogin = false
 6→let keycloak: Keycloak | null = null
 7→
 8→export async function initAuth(): Promise<boolean> {
 9→  const res = await fetch('/api/auth/config')
10→  const config = await res.json()
11→  autoLogin = config.autoLogin
12→
13→  if (autoLogin) return true
14→
15→  keycloak = new Keycloak({
16→    url: import.meta.env.VITE_KEYCLOAK_URL || 'http://localhost:8080',
17→    realm: import.meta.env.VITE_KEYCLOAK_REALM || 'upomgtu',
18→    clientId: import.meta.env.VITE_KEYCLOAK_CLIENT_ID || 'upomgtu',
19→  })
20→
21→  let authenticated = false
22→  try {
23→    authenticated = await keycloak.init({
24→      onLoad: 'login-required',
25→      checkLoginIframe: false,
26→      responseMode: 'query',
27→    })
28→  } finally {
29→    const url = new URL(window.location.href)
30→    const keycloakParams = ['state', 'session_state', 'code', 'iss']
31→    keycloakParams.forEach((p) => url.searchParams.delete(p))
32→    url.hash = ''
33→    window.history.replaceState(null, '', url.pathname + url.search)
34→  }
35→
36→  if (authenticated) {
37→    setInterval(async () => {
38→      try {
39→        await keycloak!.updateToken(30)
40→      } catch {
41→        keycloak!.login()
42→      }
43→    }, 10_000)
44→  }
45→
46→  return authenticated
47→}
48→
49→export function getToken(): string | undefined {
50→  if (autoLogin) return undefined
51→  return keycloak?.token
52→}
53→
54→export function logout(): void {
55→  if (autoLogin) {
56→    window.location.reload()
57→    return
58→  }
59→  keycloak?.logout({ redirectUri: window.location.origin })
60→}
61→
62→export function getUserRoles(): string[] {
63→  if (autoLogin) return ALL_ROLES
64→  return keycloak?.realmAccess?.roles ?? []
65→}
